const liveUrl='<?=BASE_URL?>hoclieu_game_olympia_live.php';async function sync(status,extra={}){let q=questions[index]||{},state={status,question_index:index,stage:q.stage_name||'',question:q.question_text||'',answer:q.answer_text||'',points:Number(q.points||0),seconds:Number(time||0),total_score:Number($('totalScore').textContent||0),...extra},body=new URLSearchParams({csrf:'<?=e($csrf)?>',week:'<?=e($weekId)?>',class:'<?=e($classId)?>',state:JSON.stringify(state)});try{await fetch(liveUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body})}catch(e){}}
const stageOrder=['Khởi động','Vượt chướng ngại vật','Tăng tốc','Về đích'],stageColors={'Khởi động':'#168bd2','Vượt chướng ngại vật':'#8e44ad','Tăng tốc':'#e67e22','Về đích':'#d9364f'},stageTimes={'Khởi động':30,'Vượt chướng ngại vật':45,'Tăng tốc':30,'Về đích':60};let index=0,tick=null,time=30,stageStartTotal=Number(document.getElementById('totalScore').textContent||0);
const $=id=>document.getElementById(id);function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function renderStages(){let current=questions[index].stage_name;$('stagebar').innerHTML=stageOrder.map(x=>`<div class="stagepill ${x===current?'on':''}" style="--stage:${stageColors[x]}">${x}</div>`).join('')}
let questionEnded=false,scorePublished=false,stageIntroduced=false,paused=false,timerRunning=false;function setQuestionActions(enabled){$('startBtn').disabled=!enabled;$('answerBtn').disabled=!enabled;$('endBtn').disabled=!enabled;$('saveBtn').disabled=true;$('nextBtn').disabled=true;$('pauseBtn').disabled=true}function render(mode='welcome'){clearInterval(tick);let q=questions[index],stage=q.stage_name||'Khởi động';questionEnded=false;scorePublished=false;paused=false;timerRunning=false;stageIntroduced=mode==='stage_intro';document.documentElement.style.setProperty('--stage',stageColors[stage]||'#168bd2');renderStages();$('round').textContent=stage+' · Câu '+(questions.slice(0,index+1).filter(x=>x.stage_name===stage).length)+' · '+q.points+' điểm';$('qtext').textContent=q.question_text;$('answer').textContent='ĐÁP ÁN: '+q.answer_text;time=stageTimes[stage]||30;$('timer').textContent=time;$('timer').style.borderColor='#ffd52a';$('studentGrid').innerHTML=students.map(s=>`<label class="student"><input type="checkbox" value="${esc(s.id)}" ${(selected[q.id]||[]).includes(s.id)?'checked':''}> ${esc(s.name)}</label>`).join('');$('stageBtn').disabled=mode==='question';$('stageBtn').textContent=stageIntroduced?'Vào câu hỏi':'Bắt đầu phần thi';setQuestionActions(mode==='question');sync(mode,mode==='stage_intro'?{stage}:{} )}function beginTimer(){clearInterval(tick);timerRunning=true;paused=false;$('pauseBtn').disabled=false;$('pauseBtn').textContent='Tạm dừng';sync('question',{timer_ends_at:Date.now()+time*1000});tick=setInterval(()=>{time--;$('timer').textContent=time;if(time<=5)$('timer').style.borderColor='#ff4b4b';if(time<=0){clearInterval(tick);timerRunning=false;$('timer').textContent='HẾT';$('pauseBtn').disabled=true}},1000)}
$('stageBtn').onclick=()=>{let stage=questions[index].stage_name||'Khởi động';if(!stageIntroduced){stageIntroduced=true;$('stageBtn').textContent='Vào câu hỏi';sync('stage_intro',{stage});return}$('stageBtn').disabled=true;setQuestionActions(true);sync('question')};$('welcomeBtn').onclick=()=>sync('welcome');$('startBtn').onclick=()=>{$('startBtn').disabled=true;beginTimer()};$('answerBtn').onclick=()=>sync('answer');$('endBtn').onclick=()=>{clearInterval(tick);timerRunning=false;questionEnded=true;$('timer').textContent='HẾT';$('endBtn').disabled=true;$('pauseBtn').disabled=true;if(isAdmin)$('saveBtn').disabled=false;else{$('nextBtn').disabled=false;scorePublished=true}sync('scoring',{rankings:latestRankings})};
$('pauseBtn').onclick=()=>{if(!paused){clearInterval(tick);paused=true;timerRunning=false;$('pauseBtn').textContent='Tiếp tục thi';sync('paused',{seconds:time})}else{beginTimer()}};function finishContest(){if(!confirm('Thầy/cô có chắc chắn muốn kết thúc toàn bộ nội dung thi? Thao tác này sẽ dừng phần đang chơi.'))return;clearInterval(tick);sync('finished',{stage:'Kết quả chung',stage_score:Number($('totalScore').textContent||0),total_score:Number($('totalScore').textContent||0),rankings:latestRankings});document.querySelectorAll('button').forEach(b=>b.disabled=true);$('finishBtn').textContent='Cuộc thi đã kết thúc';$('summaryFinishBtn').textContent='Cuộc thi đã kết thúc'}$('finishBtn').onclick=finishContest;$('summaryFinishBtn').onclick=finishContest;
$('saveBtn').onclick=async()=>{let q=questions[index],ids=[...$('studentGrid').querySelectorAll('input:checked')].map(x=>x.value),names=students.filter(s=>ids.includes(s.id)).map(s=>s.name),body=new URLSearchParams({csrf:'<?=e($csrf)?>',week:'<?=e($weekId)?>',class:'<?=e($classId)?>',question_id:q.id});ids.forEach(id=>body.append('student_ids[]',id));$('saveBtn').disabled=true;try{let res=await fetch(location.href,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body}),data=await res.json();if(!data.ok)throw new Error(data.message||'Không lưu được điểm');selected[q.id]=ids;latestRankings=Array.isArray(data.rankings)?data.rankings:latestRankings;$('totalScore').textContent=data.total;scorePublished=true;$('nextBtn').disabled=false;sync('score_result',{awarded_students:names,total_score:Number(data.total),question_score:ids.length*Number(q.points||0),rankings:latestRankings})}catch(e){alert(e.message);$('saveBtn').disabled=false}};
$('nextBtn').onclick=()=>{if(!scorePublished)return;let q=questions[index],next=questions[index+1],finished=!next||next.stage_name!==q.stage_name;if(finished){$('game').classList.add('hide');$('summary').classList.remove('hide');$('summaryLabel').textContent=q.stage_name;$('stageScore').textContent=Number($('totalScore').textContent)-stageStartTotal;$('continueBtn').textContent=next?'Giới thiệu phần thi tiếp theo':'Xem kết quả chung';sync(next?'stage_summary':'finished',{stage:q.stage_name,stage_score:Number($('totalScore').textContent)-stageStartTotal,total_score:Number($('totalScore').textContent),rankings:latestRankings});stageStartTotal=Number($('totalScore').textContent)}else{index++;render('question')}};
$('continueBtn').onclick=()=>{if(index+1>=questions.length){location.href='<?=BASE_URL?>hoclieu_game_olympia_rankings.php?period=week&week=<?=e($weekId)?>'}else{index++;$('summary').classList.add('hide');$('game').classList.remove('hide');render('stage_intro')}};render('welcome');
</script><?php endif?></body></html>
